using System.Globalization;
using System.Text;
using System.Text.Json.Nodes;
using System.Text.RegularExpressions;

namespace StatsKit;

/// <summary>
/// Formats of the report in the locale of the texts, rebuilt from a snapshot of Intl (Data/intl.json, generated by
/// <c>npm run dotnet:data</c>): the same strings as the Node server, whatever the globalization data of the machine.
/// Regional tags outside the snapshot use the formats of their language.
/// </summary>
public static partial class Format
{
    private sealed record TagData(
        string Group, string Decimal, int MinGroup, string[] Number, string[] Percent, string[] Plural, string PluralMillion,
        Dictionary<string, Dictionary<string, string>> Units, string[] Dm, string[] Dmy, string[] LongMonths, string[] LongWeekdays,
        string[] ShortMonths, string[] ShortWeekdays, string[] WeekdaysLong, string[] WeekdaysShort, string[] Hours, string[] Day);

    private sealed record NameData(Dictionary<string, string> Regions, Dictionary<string, string> Languages, string Pattern, Dictionary<string, string> Dialects);

    private static readonly Lazy<JsonObject> Data = new(() => (JsonObject)JsonNode.Parse(Texts.Resource("StatsKit.intl.json"))!);
    private static readonly Dictionary<string, TagData> TagCache = [];
    private static readonly Dictionary<string, NameData> NameCache = [];
    private static readonly Lock Gate = new();

    private static string[] Strings(JsonNode? n) => n is JsonArray a ? [.. a.Select(x => (string)x!)] : [];
    private static Dictionary<string, string> Map(JsonNode? n) => n is JsonObject o ? o.ToDictionary(p => p.Key, p => (string)p.Value!) : [];

    private static TagData Tag(string locale)
    {
        lock (Gate)
        {
            if (TagCache.TryGetValue(locale, out var cached)) return cached;
            var tags = (JsonObject)Data.Value["tags"]!;
            var canonical = Texts.Canonical(locale) ?? "en";
            var lang = canonical.Split('-')[0];
            var key = tags.ContainsKey(canonical) ? canonical : (string?)Data.Value["defaults"]![lang] ?? "en-GB";
            var t = (JsonObject)tags[key]!;
            var data = new TagData(
                (string)t["group"]!, (string)t["decimal"]!, (int)t["minGroup"]!,
                [(string)t["number"]!["pos"]!, (string)t["number"]!["plus"]!, (string)t["number"]!["neg"]!],
                [(string)t["percent"]!["pos"]!, (string)t["percent"]!["plus"]!, (string)t["percent"]!["neg"]!],
                ((string)t["plural"]!).Split(','), (string)t["pluralMillion"]!,
                ((JsonObject)t["units"]!).ToDictionary(u => u.Key, u => Map(u.Value)),
                Strings(t["dm"]), Strings(t["dmy"]), Strings(t["long"]!["months"]), Strings(t["long"]!["weekdays"]),
                Strings(t["dmShort"]!["months"]), Strings(t["dmShort"]!["weekdays"]),
                Strings(t["weekdays"]!["long"]), Strings(t["weekdays"]!["short"]), Strings(t["hours"]), Strings(t["day"]));
            return TagCache[locale] = data;
        }
    }

    private static NameData Names(string locale)
    {
        lock (Gate)
        {
            var lang = (Texts.Canonical(locale) ?? "en").Split('-')[0];
            if (NameCache.TryGetValue(lang, out var cached)) return cached;
            var names = (JsonObject)Data.Value["names"]!;
            var n = (JsonObject)(names[lang] ?? names["en"])!;
            return NameCache[lang] = new NameData(Map(n["regions"]), Map(n["languages"]), (string)n["pattern"]!, Map(n["dialects"]));
        }
    }

    /// <summary>Plural category of a whole number ("one", "few", "many", "other"), as <c>Intl.PluralRules</c> gives it.</summary>
    internal static string PluralCategory(string locale, double n)
    {
        var t = Tag(locale);
        var i = (long)Math.Abs(n);
        if (i < 200) return t.Plural[i];
        return i % 1_000_000 == 0 ? t.PluralMillion : t.Plural[100 + i % 100];
    }

    /// <summary>Digits of a positive rounded value, grouped as the locale does.</summary>
    private static string Digits(TagData t, decimal value, int digits)
    {
        var text = value.ToString("F" + digits, CultureInfo.InvariantCulture);
        var dot = text.IndexOf('.');
        var integer = dot < 0 ? text : text[..dot];
        var fraction = dot < 0 ? "" : text[(dot + 1)..];
        if (t.Group.Length > 0 && integer.Length >= 4 && (t.MinGroup == 1 || integer.Length >= 5))
        {
            var sb = new StringBuilder();
            for (var i = 0; i < integer.Length; i++)
            {
                if (i > 0 && (integer.Length - i) % 3 == 0) sb.Append(t.Group);
                sb.Append(integer[i]);
            }
            integer = sb.ToString();
        }
        return fraction.Length > 0 ? integer + t.Decimal + fraction : integer;
    }

    private static string Signed(string[] templates, double v, decimal rounded, string digits, bool signed)
    {
        var template = signed
            ? rounded == 0 ? templates[0] : rounded > 0 ? templates[1] : templates[2]
            : v < 0 || double.IsNegative(v) ? templates[2] : templates[0];
        return template.Replace("{n}", digits);
    }

    /// <summary>Number in the locale ("1,234", "1 234", "1.234"); "—" if it is not finite. <paramref name="signed"/> adds "+".</summary>
    public static string Number(Texts texts, double v, int digits = 0, bool signed = false)
    {
        if (!double.IsFinite(v)) return "—";
        var t = Tag(texts.Locale);
        var rounded = Math.Round(Js.Exact(v), digits, MidpointRounding.AwayFromZero);
        return Signed(t.Number, v, rounded, Digits(t, Math.Abs(rounded), digits), signed);
    }

    /// <summary>Rate (0 to 1) as a percentage in the locale ("12.5%", "12,5 %").</summary>
    public static string Percent(Texts texts, double v, int digits = 1, bool signed = false)
    {
        if (!double.IsFinite(v)) return "—";
        var t = Tag(texts.Locale);
        var rounded = Math.Round(Js.Exact(v) * 100, digits, MidpointRounding.AwayFromZero);
        return Signed(t.Percent, v, rounded, Digits(t, Math.Abs(rounded), digits), signed);
    }

    private static string Unit(Texts texts, double n, string unit)
    {
        var templates = Tag(texts.Locale).Units[unit];
        var template = templates.GetValueOrDefault(PluralCategory(texts.Locale, n)) ?? templates.GetValueOrDefault("other") ?? templates.Values.First();
        return template.Replace("{n}", Number(texts, n));
    }

    /// <summary>Duration in seconds: "2 min 5 s", "42 sec", "—" if zero.</summary>
    public static string Duration(Texts texts, double seconds)
    {
        if (!double.IsFinite(seconds) || seconds <= 0) return "—";
        var s = Js.Round(seconds);
        return s >= 60 ? $"{Unit(texts, Math.Floor(s / 60), "minute")} {Unit(texts, s % 60, "second")}" : Unit(texts, s, "second");
    }

    /// <summary>Relative change as a whole percentage, or null without a basis for comparison.</summary>
    public static double? PercentChange(double now, double? before) =>
        before is { } b && b != 0 && !double.IsNaN(b) ? Js.Round((now - b) / b * 100) : null;

    /// <summary>Label and value joined the way the language does it ("Visitors: 12", "Visiteurs : 12").</summary>
    public static string LabelValue(Texts texts, string label, string value) =>
        Texts.Fill(texts["common.labelValue"], new Dictionary<string, string> { ["label"] = label, ["value"] = value });

    private static (int Y, int M, int D, int H) SlotParts(string slot)
    {
        static int N(string s, int start, int length) => s.Length >= start + length && int.TryParse(s.AsSpan(start, length), NumberStyles.None, CultureInfo.InvariantCulture, out var v) ? v : 0;
        return (N(slot, 0, 4), N(slot, 5, 2), N(slot, 8, 2), slot.Length >= 13 ? N(slot, 11, 2) : 0);
    }

    private static int Weekday(int y, int m, int d) => ((int)new DateTime(y, 1, 1).AddMonths(m - 1).AddDays(d - 1).DayOfWeek + 6) % 7;

    private static string Date(string template, TagData t, int y, int d, string weekday = "") =>
        template.Replace("{d}", t.Day[d - 1]).Replace("{y}", y.ToString(CultureInfo.InvariantCulture)).Replace("{w}", weekday);

    /// <summary>Name of a weekday (Monday = 0): "Monday" / "Mon".</summary>
    public static string WeekdayName(Texts texts, int day, bool shortName = false)
    {
        var t = Tag(texts.Locale);
        return (shortName ? t.WeekdaysShort : t.WeekdaysLong)[day];
    }

    /// <summary>Hour of the day (0 to 23): "09:00", "9 AM"…</summary>
    public static string HourName(Texts texts, int hour) => Tag(texts.Locale).Hours[hour];

    /// <summary>Label of a slot: hour ("14:00"), short day ("16 Nov") or long day ("Mon 16 Nov").</summary>
    public static string SlotLabel(Texts texts, string slot, string unit, bool longLabel = false)
    {
        var t = Tag(texts.Locale);
        var (y, m, d, h) = SlotParts(slot);
        if (unit == "hour") return t.Hours[h];
        return longLabel ? Date(t.ShortMonths[m - 1], t, y, d, t.ShortWeekdays[Weekday(y, m, d)]) : Date(t.Dm[m - 1], t, y, d);
    }

    /// <summary>Day "YYYY-MM-DD" in full: "Monday 16 November".</summary>
    public static string LongDay(Texts texts, string ymd)
    {
        var t = Tag(texts.Locale);
        var (y, m, d, _) = SlotParts(ymd);
        return Date(t.LongMonths[m - 1], t, y, d, t.LongWeekdays[Weekday(y, m, d)]);
    }

    /// <summary>Day "YYYY-MM-DD" or ISO instant (read in <paramref name="timeZone"/>), short: "16 Nov" / "16 Nov 2026".</summary>
    public static string ShortDate(Texts texts, string value, string timeZone = "UTC", bool withYear = false)
    {
        var t = Tag(texts.Locale);
        int y, m, d;
        if (DayPattern().IsMatch(value)) (y, m, d, _) = SlotParts(value);
        else
        {
            var ms = Js.ParseInstant(value);
            if (double.IsNaN(ms)) return value;
            var p = Time.ZonedParts(ms, timeZone);
            (y, m, d) = (p.Y, p.M, p.D);
        }
        return Date((withYear ? t.Dmy : t.Dm)[m - 1], t, y, d);
    }

    [GeneratedRegex(@"^\d{4}-\d{2}-\d{2}$")]
    private static partial Regex DayPattern();

    /// <summary>Busiest slot of a 7 × 24 heatmap, or null if it is empty.</summary>
    public static (int Day, int Hour, double Value)? BestSlot(IReadOnlyList<IReadOnlyList<double>>? grid)
    {
        (int, int, double) best = (0, 0, 0);
        if (grid is not null)
            for (var day = 0; day < grid.Count; day++)
                for (var hour = 0; hour < grid[day].Count; hour++)
                    if (grid[day][hour] > best.Item3) best = (day, hour, grid[day][hour]);
        return best.Item3 > 0 ? best : null;
    }

    private static readonly Dictionary<string, string> Alpha3 = new()
    {
        ["FRA"] = "FR", ["CHE"] = "CH", ["BEL"] = "BE", ["LUX"] = "LU", ["MCO"] = "MC", ["CAN"] = "CA", ["USA"] = "US", ["GBR"] = "GB", ["DEU"] = "DE", ["ESP"] = "ES", ["ITA"] = "IT", ["PRT"] = "PT",
        ["NLD"] = "NL", ["IRL"] = "IE", ["AUT"] = "AT", ["SWE"] = "SE", ["NOR"] = "NO", ["DNK"] = "DK", ["FIN"] = "FI", ["POL"] = "PL", ["ROU"] = "RO", ["GRC"] = "GR", ["TUR"] = "TR", ["RUS"] = "RU",
        ["UKR"] = "UA", ["CHN"] = "CN", ["JPN"] = "JP", ["KOR"] = "KR", ["IND"] = "IN", ["BRA"] = "BR", ["MEX"] = "MX", ["ARG"] = "AR", ["AUS"] = "AU", ["NZL"] = "NZ", ["MAR"] = "MA", ["DZA"] = "DZ",
        ["TUN"] = "TN", ["EGY"] = "EG", ["ISR"] = "IL", ["SEN"] = "SN", ["CIV"] = "CI", ["REU"] = "RE", ["NCL"] = "NC", ["CZE"] = "CZ", ["HUN"] = "HU", ["BGR"] = "BG", ["HRV"] = "HR", ["SVN"] = "SI",
        ["SVK"] = "SK", ["SRB"] = "RS", ["ZAF"] = "ZA", ["NGA"] = "NG", ["CMR"] = "CM", ["VNM"] = "VN", ["THA"] = "TH", ["IDN"] = "ID", ["PHL"] = "PH", ["SGP"] = "SG", ["ARE"] = "AE", ["SAU"] = "SA",
    };

    /// <summary>Name of a country (ISO alpha-2 or alpha-3 code) in the language of the texts, falling back to the code.</summary>
    public static string CountryName(Texts texts, string? code)
    {
        if (string.IsNullOrEmpty(code)) return texts["common.notSpecified"];
        var cc = code.Length == 3 ? Alpha3.GetValueOrDefault(code.ToUpperInvariant()) ?? code.ToUpperInvariant() : code.ToUpperInvariant();
        return Names(texts.Locale).Regions.GetValueOrDefault(cc) ?? cc;
    }

    /// <summary>Name of a language ("fr" → "French", "en-GB" → "British English"), falling back to the code.</summary>
    public static string LanguageName(Texts texts, string? code)
    {
        if (string.IsNullOrEmpty(code)) return texts["common.notSpecified"];
        var n = Names(texts.Locale);
        var tag = Texts.Canonical(code);
        if (tag is null) return code;
        if (n.Languages.TryGetValue(tag, out var name) || n.Dialects.TryGetValue(tag, out name)) return name;
        var parts = tag.Split('-');
        var lang = n.Languages.GetValueOrDefault(parts[0]) ?? parts[0];
        var region = parts.Skip(1).FirstOrDefault(p => p.Length == 2 && char.IsAsciiLetterUpper(p[0]) || p.Length == 3 && char.IsAsciiDigit(p[0]));
        return region is null ? lang : n.Pattern.Replace("{0}", lang).Replace("{1}", n.Regions.GetValueOrDefault(region) ?? region);
    }

    /// <summary>Initial capital.</summary>
    public static string Capitalize(string s) => s.Length > 0 ? char.ToUpperInvariant(s[0]) + s[1..] : s;

    /// <summary>Label of an Umami device.</summary>
    public static string DeviceName(Texts texts, string code) => texts.Entry("devices", code) ?? Capitalize(code);

    private static readonly Dictionary<string, string> Browsers = new()
    {
        ["chrome"] = "Chrome", ["crios"] = "Chrome (iOS)", ["ios"] = "Safari (iOS)", ["ios-webview"] = "iOS (WebView)", ["safari"] = "Safari", ["firefox"] = "Firefox", ["fxios"] = "Firefox (iOS)",
        ["edge-chromium"] = "Edge", ["edge"] = "Edge", ["edge-ios"] = "Edge (iOS)", ["samsung"] = "Samsung Internet", ["android"] = "Android", ["chromium-webview"] = "Android (WebView)",
        ["opera"] = "Opera", ["yandexbrowser"] = "Yandex", ["facebook"] = "Facebook", ["instagram"] = "Instagram", ["silk"] = "Silk", ["miui"] = "MIUI",
    };

    /// <summary>Name of a browser as Umami codes it ("edge-chromium" → "Edge").</summary>
    public static string BrowserName(string code) => Browsers.GetValueOrDefault(code) ?? Capitalize(code);

    /// <summary>Upper case as <c>toLocaleUpperCase</c> gives it for the shipped languages ("ß" → "SS").</summary>
    public static string Upper(string s) => s.ToUpperInvariant().Replace("ß", "SS", StringComparison.Ordinal);

    /// <summary>Mix of two "#rrggbb" colours (t from 0 to 1).</summary>
    public static string MixHex(string a, string b, double t)
    {
        var x = Rgb(a);
        var y = Rgb(b);
        return "#" + string.Concat(Enumerable.Range(0, 3).Select(i => ((int)Js.Round(x[i] + (y[i] - x[i]) * t)).ToString("x2", CultureInfo.InvariantCulture)));
    }

    /// <summary>"#rrggbb" → [r, g, b].</summary>
    public static int[] Rgb(string hex) => [.. new[] { 1, 3, 5 }.Select(i => int.Parse(hex.AsSpan(i, 2), NumberStyles.HexNumber, CultureInfo.InvariantCulture))];
}
